1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Single source of truth for an owner's duplicate-detection identity key, shared by the
7	 * owner-create pipeline. The key consolidates the former separate telephone, email and
8	 * household duplicate checks into one derived value so two owners conflict only when their
9	 * whole keys are equal.
10	 *
11	 * <p>The key is {@code normalizedTelephone + "|" + (email or "") + "|" + (householdId or "")}.
12	 * Because the telephone is part of the key, two members of the same household (same
13	 * {@code householdId}) with different telephones derive different keys and are both allowed;
14	 * only an exact full-key match is a duplicate.
15	 */
16	public final class OwnerIdentity {
17	
18	    private OwnerIdentity() {
19	    }
20	
21	    /**
22	     * Build the identity key from already-normalized parts: a normalized E.164 telephone, a
23	     * lower-cased email (or {@code null}) and a household id (or {@code null}). A {@code null}
24	     * segment is rendered as empty.
25	     */
26	    static String key(String normalizedTelephone, String email, String householdId) {
27	        return orEmpty(normalizedTelephone) + "|" + orEmpty(email) + "|" + orEmpty(householdId);
28	    }
29	
30	    /**
31	     * The identity key of an owner, re-deriving the normalized telephone and email from the
32	     * stored values so it compares identically to a freshly built key and can be derived at the
33	     * Owner-to-DTO boundary for any response.
34	     */
35	    public static String of(Owner owner) {
36	        return key(OwnerTelephone.normalize(owner.getTelephone()),
37	                OwnerEmail.normalize(owner.getEmail()), owner.getHouseholdId());
38	    }
39	
40	    private static String orEmpty(String value) {
41	        return value == null ? "" : value;
42	    }
43	}
