    16	    /** City -> canonical region. Matched exactly, mirroring {@code Owner.getLocality()}. */
    17	    private static final Map<String, String> CITY_REGION = Map.of(
    18	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
    19	
    20	    /** Region -> inclusive 4-digit postcode range {low, high}. */
    21	    private static final Map<String, int[]> REGION_RANGE = Map.of(
    22	            "NSW", new int[] {2000, 2099},
    23	            "VIC", new int[] {3000, 3099},
    24	            "QLD", new int[] {4000, 4099});
    25	
    26	    private OwnerPostcode() {
    27	    }
    28	
    29	    /**
    30	     * Whether the given postcode is acceptable for the city. An absent (null/blank) postcode is
    31	     * always acceptable — validation applies only when present. A present postcode must be 4
    32	     * digits and, for a city with a known region, within that region's range; a city with no
    33	     * known region accepts any 4-digit postcode.
    34	     */
    35	    static boolean isValid(String postcode, String city) {
    36	        if (postcode == null || postcode.isBlank()) {
    37	            return true;
    38	        }
    39	        if (!postcode.matches("[0-9]{4}")) {
    40	            return false;
    41	        }
    42	        String region = city == null ? null : CITY_REGION.get(city);
    43	        if (region == null) {
    44	            return true;
    45	        }
    46	        int[] range = REGION_RANGE.get(region);
    47	        if (range == null) {
    48	            return true;
    49	        }
    50	        int value = Integer.parseInt(postcode);
    51	        return value >= range[0] && value <= range[1];
    52	    }
    53	}
