1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
8	
9	/**
10	 * Runs after {@link ValidateNewOwner} (which normalizes the telephone and email) and
11	 * {@link ResolveHousehold} (which resolves the shared {@link Household.Id}), and before
12	 * {@link BuildOwner}. The single duplicate-detection gate: it derives the new owner's
13	 * {@link OwnerIdentity identity key} and rejects the create with a 409 when any existing owner
14	 * has the same whole key, consolidating the former separate telephone, email and household
15	 * checks. Publishes nothing; it only escalates on conflict.
16	 */
17	public class ValidateUniqueIdentity {
18	
19	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
20	            OwnerRepository ownerRepository) throws DuplicateIdentityException {
21	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
22	                householdId == null ? null : householdId.value());
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (identityKey.equals(OwnerIdentity.of(existing))) {
25	                throw new DuplicateIdentityException(
26	                        "Identity key " + identityKey + " is already used by another owner");
27	            }
28	        }
29	    }
30	}
