10	
11	/**
12	 * Runs after {@link ValidateNewOwner} and before {@link ValidateUniqueIdentity}. A read-only
13	 * step that resolves the new owner's household (see {@link Household}) and publishes the
14	 * {@link Household.Id} for the rest of the pipeline — the shared identifier when the owner joins
15	 * an existing household (same last name at the same address), {@link Household.Id#ABSENT}
16	 * otherwise. It writes nothing to the database.
17	 *
18	 * <p>The household no longer rejects the create on its own: duplicate detection is now the single
19	 * {@link OwnerIdentity identity key} gate in {@link ValidateUniqueIdentity}. Because the household
20	 * id is part of that key, two members of the same household with different telephones derive
21	 * different keys and are both allowed. {@link ApplySharedHousehold} later back-fills existing
22	 * members and {@link BuildOwner} stamps the new owner with the resolved id.
23	 */
24	public class ResolveHousehold {
25	
26	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
27	            Out<Household.Id> householdIdOut) {
28	        List<Owner> members = Household.membersOf(request, ownerRepository);
29	        if (members.isEmpty()) {
30	            // Not joining any household: no shared id to publish.
31	            householdIdOut.set(Household.Id.ABSENT);
32	            return;
33	        }
34	        householdIdOut.set(Household.idFor(request));
35	    }
36	}
