169	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
170	     * (e.g. {@code 'LON-SMI-0007-M26'}).
171	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
172	     */
173	    @Transient
174	    public String getMembershipNumber() {
175	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
176	    }
177	
178	    /**
179	     * The owner's check digit: the Luhn check digit (0-9) computed over the digits contained
180	     * in the {@link #getCustomerCode() customerCode}. Non-digit characters are ignored.
181	     * Not persisted — derived from {@link #getCustomerCode()}.
182	     */
183	    @Transient
184	    public int getCheckDigit() {
185	        int sum = 0;
186	        boolean dbl = true;
187	        String code = this.customerCode == null ? "" : this.customerCode;
188	        for (int i = code.length() - 1; i >= 0; i--) {
189	            char c = code.charAt(i);
190	            if (c < '0' || c > '9') {
191	                continue;
192	            }
193	            int d = c - '0';
194	            if (dbl) {
195	                d *= 2;
196	                if (d > 9) {
197	                    d -= 9;
198	                }
199	            }
200	            sum += d;
201	            dbl = !dbl;
