214	        int level = 1;
215	        boolean hasEmail = this.email != null && !this.email.isBlank();
216	        if (hasEmail) {
217	            level++;
218	        }
219	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
