231	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
232	
233	    /**
234	     * Region -> inclusive 4-digit postcode range {low, high}, the primary source for
235	     * deriving {@link #getLocality() locality} (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
236	     */
237	    private static final Map<String, int[]> REGION_RANGE = Map.of(
238	        "NSW", new int[] {2000, 2099},
239	        "VIC", new int[] {3000, 3099},
240	        "QLD", new int[] {4000, 4099});
241	
242	    /**
243	     * The owner's locality: the canonical region derived first from {@link #getPostcode()
244	     * postcode} by range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the
245	     * fixed {@link #CITY_REGION} city table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when
246	     * the postcode is absent or in no known range, or {@code 'UNKNOWN'} when neither matches.
247	     * Preferring the postcode disambiguates cities that share a name. Not persisted — derived
248	     * from {@link #getPostcode()} and {@link #getCity()}.
249	     */
250	    @Transient
251	    public String getLocality() {
252	        String region = regionFromPostcode();
253	        if (region != null) {
254	            return region;
255	        }
256	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
257	    }
258	
259	    /** Region whose range contains this owner's postcode, or {@code null} when the postcode is
260	     * absent, not 4 digits, or in no known range. */
261	    private String regionFromPostcode() {
262	        if (this.postcode == null || !this.postcode.matches("[0-9]{4}")) {
263	            return null;
264	        }
265	        int value = Integer.parseInt(this.postcode);
266	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
267	            int[] range = entry.getValue();
268	            if (value >= range[0] && value <= range[1]) {
269	                return entry.getKey();
270	            }
271	        }
272	        return null;
273	    }
274	
275	    /**
276	     * Whether more than 80 owners had already been created today when this response was
277	     * built. Not persisted — populated for the response by the create and fetch pipelines
278	     * and defaults to {@code false} so every owner serialization carries the flag.
279	     */
280	    @Transient
281	    public boolean isBulkSignupWarning() {
282	        return this.bulkSignupWarning;
283	    }
284	
285	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
286	        this.bulkSignupWarning = bulkSignupWarning;
287	    }
288	
289	    /**
290	     * The owner's preferred contact channel: {@code 'EMAIL'} when an {@link #getEmail() email}
291	     * is present, otherwise {@code 'PHONE'}.
292	     * Not persisted — derived from {@link #getEmail()}.
293	     */
294	    @Transient
