1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Canonical address normalization for the owner-create pipeline. Applied once when an owner is
8	 * created so the stored and returned {@code address} is canonical, and reused for every address
9	 * comparison (household duplicate detection in {@link Household} and the shared household id) so
10	 * all steps compare the same form.
11	 *
12	 * <p>Normalization: trim, collapse any run of whitespace to a single space, upper-case, and
13	 * expand common abbreviations as whole words — {@code ST -> STREET}, {@code RD -> ROAD},
14	 * {@code AVE -> AVENUE}. Yields {@code ""} for a {@code null} or whitespace-only input.
15	 */
16	final class OwnerAddress {
17	
18	    private static final Map<String, String> ABBREVIATIONS = Map.of(
19	            "ST", "STREET",
20	            "RD", "ROAD",
21	            "AVE", "AVENUE");
22	
23	    private OwnerAddress() {
24	    }
25	
26	    static String normalize(String value) {
27	        if (value == null) {
28	            return "";
29	        }
30	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
31	        if (collapsed.isEmpty()) {
32	            return "";
33	        }
34	        String[] tokens = collapsed.split(" ");
35	        StringBuilder sb = new StringBuilder(collapsed.length());
36	        for (int i = 0; i < tokens.length; i++) {
37	            if (i > 0) {
38	                sb.append(' ');
39	            }
40	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
41	        }
42	        return sb.toString();
43	    }
44	}
