    13	/**
    14	 * First step of {@code POST /api/owners}. Rejects a body that is missing or blank in any
    15	 * required field (firstName, lastName, address, city, telephone) with a 400 listing the
    16	 * offending field names, normalizes the telephone to E.164 form (400 if it cannot form a
    17	 * valid E.164 number), then publishes the body for {@link BuildOwner}.
    18	 *
    19	 * <p>Runs before {@link BuildOwner} and binds {@code @RequestBody} without {@code @Valid}
    20	 * so the required-field check produces the {@code errors} response shape rather than the
    21	 * generic schema-validation shape, and so an invalid body is a 400 here.
    22	 */
    23	public class ValidateNewOwner {
    24	
    25	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
    26	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
    27	        // Normalize the address up front so the required-field check sees the canonical form
    28	        // (an address blank after normalization is rejected) and every later step — storage,
    29	        // the response and household comparisons — carries the same normalized value.
    30	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
    31	        List<String> missing = new ArrayList<>();
    32	        if (isBlank(request.getFirstName())) {
    33	            missing.add("firstName");
    34	        }
    35	        if (isBlank(request.getLastName())) {
    36	            missing.add("lastName");
    37	        }
    38	        if (isBlank(request.getAddress())) {
    39	            missing.add("address");
    40	        }
    41	        if (isBlank(request.getCity())) {
    42	            missing.add("city");
    43	        }
    44	        if (isBlank(request.getTelephone())) {
    45	            missing.add("telephone");
    46	        }
    47	        if (!missing.isEmpty()) {
    48	            throw new MissingOwnerFieldsException(missing);
    49	        }
    50	        String e164 = OwnerTelephone.normalize(request.getTelephone());
    51	        if (e164 == null) {
    52	            throw new InvalidTelephoneException(
    53	                    "Telephone is not a valid E.164 number: " + request.getTelephone());
    54	        }
    55	        request.setTelephone(e164);
    56	        String email = OwnerEmail.normalize(request.getEmail());
    57	        if (email != null && !OwnerEmail.isValid(email)) {
    58	            throw new InvalidEmailException("Email is not a valid address: " + request.getEmail());
    59	        }
    60	        request.setEmail(email);
    61	        validated.set(request);
    62	    }
    63	
    64	    private static boolean isBlank(String value) {
    65	        return value == null || value.isBlank();
    66	    }
    67	}
